// The safe expression compiler — no eval, no Function. Recursive descent over
// a whitelisted grammar; any illegal token throws instead of executing.
function makeFn(src) {
  var s = String(src), i = 0;
  var FUNCS = { sin: Math.sin, cos: Math.cos, tan: Math.tan,
                exp: Math.exp, log: Math.log, sqrt: Math.sqrt, abs: Math.abs };
  var CONSTS = { pi: Math.PI, e: Math.E };
  function ws() { while (i < s.length && s.charAt(i) === ' ') i++; }
  function konst(v) { return function () { return v; }; }
  function parseExpr() {
    var f = parseTerm(); ws();
    while (s.charAt(i) === '+' || s.charAt(i) === '-') {
      var op = s.charAt(i++); var g = parseTerm();
      f = (function (f, g, op) {
        return op === '+' ? function (x) { return f(x) + g(x); }
                          : function (x) { return f(x) - g(x); };
      })(f, g, op); ws();
    }
    return f;
  }
  function parseTerm() {
    var f = parseFactor(); ws();
    while (s.charAt(i) === '*' || s.charAt(i) === '/') {
      var op = s.charAt(i++); var g = parseFactor();
      f = (function (f, g, op) {
        return op === '*' ? function (x) { return f(x) * g(x); }
                          : function (x) { return f(x) / g(x); };
      })(f, g, op); ws();
    }
    return f;
  }
  function parseFactor() {
    var b = parseBase(); ws();
    if (s.charAt(i) === '^') { i++; var e = parseFactor();
      return function (x) { return Math.pow(b(x), e(x)); }; }
    return b;
  }
  function parseBase() {
    ws();
    var c = s.charAt(i);
    if (c === '-') { i++; var b = parseBase(); return function (x) { return -b(x); }; }
    if (c === '+') { i++; return parseBase(); }
    if (c === '(') { i++; var e = parseExpr(); ws();
      if (s.charAt(i) !== ')') throw new Error('expected )'); i++; return e; }
    if ((c >= '0' && c <= '9') || c === '.') {
      var j = i; while (i < s.length && /[0-9.]/.test(s.charAt(i))) i++;
      var num = parseFloat(s.slice(j, i));
      if (!isFinite(num)) throw new Error('bad number'); return konst(num);
    }
    if (/[a-z]/i.test(c)) {
      var j2 = i; while (i < s.length && /[a-z]/i.test(s.charAt(i))) i++;
      var name = s.slice(j2, i).toLowerCase(); ws();
      if (s.charAt(i) === '(') {
        if (!FUNCS[name]) throw new Error('unknown function ' + name);
        i++; var arg = parseExpr(); ws();
        if (s.charAt(i) !== ')') throw new Error('expected )'); i++;
        var fn = FUNCS[name];
        return function (x) { return fn(arg(x)); };
      }
      if (name === 'x') return function (x) { return x; };
      if (CONSTS.hasOwnProperty(name)) return konst(CONSTS[name]);
      throw new Error('unknown name ' + name);
    }
    throw new Error('unexpected "' + c + '"');
  }
  var f = parseExpr(); ws();
  if (i < s.length) throw new Error('trailing "' + s.slice(i) + '"');
  return f;
}

// Prove it works and prove it's safe.
const sin = makeFn('sin(x)');
const poly = makeFn('x*x*x - x');
const bell = makeFn('exp(-x*x)');

console.log('sin(0)      =', sin(0).toFixed(3));
console.log('sin(pi/2)   =', makeFn('sin(pi/2)')(0).toFixed(3));
console.log('(x³−x) at 2 =', poly(2));            // 6
console.log('bell(0)     =', bell(0).toFixed(3));  // 1.000

let rejected = false;
try { makeFn('x; while(true){}'); }        // not in the grammar
catch (e) { rejected = true; console.log('rejected unsafe input:', e.message); }

return {
  'sin(0)': sin(0),
  'poly(2)': poly(2),
  unsafeRejected: rejected,   // true — the grammar has no ';' or identifiers-as-code
  note: 'the HTML cell embeds this same compiler to sample the curve live',
};
